def design(feats):
    X = np.asarray(feats.x, float)
    y = np.asarray(feats.y).ravel()
    ids = list(feats.ids)
    p = len(ids)
    y1 = y == 1
    if p == 0 or y1.sum() == 0 or y1.all():
        return Design(drivers=(), columns=(), products=(), loadings={})
    Z = np.nan_to_num(X - X.mean(0))
    s = Z.std(0)
    s[s == 0] = 1.0
    Z /= s
    n0, n1 = int((~y1).sum()), int(y1.sum())

    def tstat(v):
        a, b = v[y1], v[~y1]
        d = np.sqrt(a.var() / n1 + b.var() / n0)
        return 0.0 if d == 0 else float((a.mean() - b.mean()) / d)

    t = np.array([tstat(Z[:, j]) for j in range(p)])
    C = np.nan_to_num((Z.T @ Z) / max(Z.shape[0] - 1, 1))
    np.fill_diagonal(C, 0.0)
    A = np.abs(C)
    strong = A >= 0.6

    # Candidate co-regulated modules: a dense core per well-connected seed.
    seen, scored = set(), []
    for seed in np.argsort(-(strong.sum(0) + A.sum(0) * 1e-3)):
        if strong[seed].sum() < 2:
            break
        cand = [int(seed)] + np.where(strong[seed])[0].tolist()
        core = tuple(sorted(j for j in cand
                            if A[j, cand].sum() >= 0.6 * (len(cand) - 1)))
        if len(core) >= 3 and core not in seen:
            seen.add(core)
            _, V = np.linalg.eigh(C[np.ix_(core, core)])
            scored.append((abs(tstat(Z[:, list(core)] @ V[:, -1])), core, V[:, -1]))

    drivers, loadings = (), {}
    in_module = np.zeros(p, bool)
    if scored:
        ts, core, v = max(scored)
        if ts >= 2.5:  # the module's shared score tracks the outcome
            if v[np.argmax(np.abs(v))] < 0:
                v = -v
            order = sorted(range(len(core)), key=lambda k: -abs(v[k]))
            drivers = tuple(ids[core[k]] for k in order[:MAX_DRIVERS])
            loadings = {ids[core[k]]: float(v[k]) for k in range(len(core))}
            in_module[list(core)] = True

    if not drivers:  # fall back to strong, non-duplicate univariate signals
        pick = []
        for j in np.argsort(-np.abs(t)):
            if abs(t[j]) < 3.3 or len(pick) >= MAX_DRIVERS:
                break
            if all(A[j, k] < 0.85 for k in pick):
                pick.append(int(j))
        drivers = tuple(ids[j] for j in pick)

    cols = []  # regression inputs: top marginal signals, one per near-duplicate
    for j in np.argsort(-np.abs(t)):
        if len(cols) >= 6 or abs(t[j]) < 1.5:
            break
        if in_module[j] or any(A[j, k] >= 0.85 for k in cols):
            continue
        cols.append(int(j))

    return Design(drivers=drivers, columns=tuple(ids[j] for j in cols),
                  products=(), loadings=loadings)

